#!/bin/bash
##############################################################
# Author: Petr Bardonek ibardonek@fit.vut.cz
# Language: Bash
# Description: Shell script for running the UVM verification
##############################################################
# Simulator select
RUN_CMD="vsim"
EDA_SIM="questasim"
# Simulator options
VSIM_OPT="-gui"

UVM_TESTNAME=0
UVM_TESTS_FILE=0
RUN_MULTIPLE_TESTS=0

ARGV=$*

if [ $# -gt 0 ]; then
    for args in $ARGV; do
        case $args in
            -c)
                delete="-c"
                VSIM_OPT="-c"
                ;;
            -gui)
                delete="-gui"
                VSIM_OPT="-gui"
                ;;
            -uvm_testname)
                UVM_TESTNAME=1
                ;;
            -uvm_tests_file)
                UVM_TESTS_FILE=1
                ;;
            -run_multiple_tests)
                RUN_MULTIPLE_TESTS=1
                ;;
            -questasim)
                delete="-questasim"
                EDA_SIM="questasim"
                RUN_CMD="vsim"
                ;;
            -xcelium)
                delete="-xcelium"
                EDA_SIM="xcelium"
                ;;
            -clean)
                rm -rf work/ ucdb/ covhtmlreport/ transcript vsim.wlf report.txt merged.ucdb
                exit 0
                ;;
            -h | -help)
                echo "USAGE: ./start_verification.sh -c -gui -uvm_testname uvm_class_name -uvm_tests_file path_to_tests_file -run_multiple_tests"
                echo "Parameters:
                    -c -- Run simulator in command line mode (optional)
                    -gui -- Run simulator in gui mode (optional)
                    -uvm_testname -- Specify which UVM test to execute (optional)
                    -uvm_tests_file -- Specify location of the file with list of test names (optional)
                    -run_multiple_tests -- Run all tests specified in file with list of test names (optional)
                    -trans_cnt -- Number of transactions to be generated with random sequences (optional)
                    -seed -- Number to be used as a seed for randomization (optional)
                    -clean -- Remove files generated by the simulation includig work folder, ucdb folder, transcript file, vsim.wlf file
                    -h, -help -- Print Usage and Parameters
                    "
                    exit 0
                ;;
        esac
        ARGV=${ARGV[@]/$delete/}
    done
    if [ ${RUN_MULTIPLE_TESTS} -eq 1 ]; then
      echo "Forcing comandline simulator run, as run of multiple tests was requested"
      VSIM_OPT="-c"
    fi
fi

# append chosen option cmdline or gui
RUN_CMD="${RUN_CMD} ${VSIM_OPT}"

if [ "$EDA_SIM" == "questasim" ]
then
    ${RUN_CMD} -do "do eda_scripts/questa/start.tcl $ARGV" #$@
else
    echo "TBD xcelium"
fi
